#!/bin/bash
# RPD-RECO P0 for e1 (rpd_p0; RPD-RECO amendment 1, generated from p0-20261123 at 2415e8d6): the login-node connect.
# P0 is login-only at 0 node-h, with no job (FD-RPD-RECO-DECLARATION section 5, BINDING-1 ruling 3). C-JOIN part 2
# runs in its p0 step. It reads flux4's records and products (run-62051670) in place. It runs only on the
# director's go for its exact sha256. In order, on one login node:
#   1. refuses unless on a login node with the literal root /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126 absent;
#   2. the sacct fence (any unended cov2d*, t2a*, rpd* or geanttw* job refuses; flux4's block, byte for byte);
#   3. a fresh clone at 2415e8d66d1a9160e724d426eaeb54d458d4b4f7 into the root, HEAD and porcelain checked, and the 14 pinned sha256s;
#   4. the P0 READY config, written from this script and checked against its sha256;
#   5. P0's in-place inputs: flux4's extract, custody record and 12 factor products, read with O_NOATIME and checked
#      against the committed run-62051670 records (tools/p0_checks.py inputs);
#   6. a fresh stat (never an open) of the three gen2thin flux files, the 24 dumps, the 12 RDX omnifiles and the
#      true-energy sidecar, compared with the recorded bytes and inodes (S1's for the first 27, the sidecar probe's
#      for the 13), with the earliest purge exposure printed (tools/p0_checks.py stat, recorded in stat-p0.txt);
#   7. the overlap fence (tools/fence_overlap.py, write roots /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126 and /dev/shm/limres-rpd-flux1);
#   8. the clone copied to /dev/shm/limres-rpd-flux1/repo (the path the config binds), HEAD, porcelain and pins rechecked, the config
#      copied beside it;
#   9. the runner started detached (setsid, nohup, nice 19, with SIGINT reset to its default so the runner can trap
#      it). The connect waits up to 30 s for runner.pid, checks that it names the started process and that it is
#      alive, then gives up ownership (started=1) and only then writes handoff.ok. The runner starts no step without
#      handoff.ok and cleans up itself if it is not there within 60 s, so a connect stopped in between leaves no gap.
# Until started=1, the connect owns /dev/shm/limres-rpd-flux1: on any STOP or signal (TERM, INT, HUP) it stops a started runner, as a group
# and as a process (TERM, then KILL after 5 s), reaps it and removes /dev/shm/limres-rpd-flux1, checked. Before the handoff the runner has
# started no supervisor or worker. TMPDIR is the root from step 3 on, so bash's heredoc spools stay inside it. The runner (rpd_p0_runner.sh) runs pins --dry-run and
# p0 --dry-run into /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/dry, then pins and p0 into /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/run, each under tools/p0_supervise.py with one monotonic
# deadline (7200 s for the whole chain) and a STOP over 8000000000 B peak RSS. The fetch reports RUNNING, DONE or STOP.
# Every Python call has -B. Writes only under the root and /dev/shm/limres-rpd-flux1. Nothing is written to CFS. umask 077. No set -u.
# Launched from a /dev/shm copy of itself ($1), which it deletes.
umask 077
SELF=$1
S=2415e8d66d1a9160e724d426eaeb54d458d4b4f7
CFG_SHA=f92d034df0db5bf487f689b0efc1eb8862396303647fa1172ad5e6eaa3f4c47a
FENCE_SHA=940fb7598c782c77c2b3dd0e677f80568f0fdb31fd033e8e8988404049f38810
CHECKS_SHA=bcdc1b99aa4aff1e645e8000b7630d38d3bcafda74f70b43869195dc64071008
EXPECTED_SHA=c9d5e9567eba82818616c2b25c0162f113026e5feec8d2971dbe8f18d5f3dee9
SUPERVISE_SHA=6ad0f68fb309a7b83adc0f65ed709e5e2412e650e115075fe41ebbc7a070134f
MAT_PYTHON=/global/homes/j/josephrb/.conda/envs/root_6_28/bin/python3
PY=/global/homes/j/josephrb/.conda/envs/omnifold_py310/bin/python3
made=0
started=0
spid=
launching=0
finish() {
  trap '' TERM INT HUP
  local p=$spid
  [ -z "$p" ] && [ "$launching" -eq 1 ] && p=$!
  if [ -n "$p" ] && [ "$started" -eq 0 ]; then
    kill -TERM -- -"$p" 2>/dev/null; kill -TERM "$p" 2>/dev/null
    for _ in $(seq 1 25); do ps -o stat= -p "$p" 2>/dev/null | grep -qv Z || break; sleep 0.2; done
    kill -KILL -- -"$p" 2>/dev/null; kill -KILL "$p" 2>/dev/null
    wait "$p" 2>/dev/null
    echo "stopped the runner $p before the handoff"
  fi
  if [ "$made" -eq 1 ] && [ "$started" -eq 0 ]; then
    rm -rf -- /dev/shm/limres-rpd-flux1
    if [ -e /dev/shm/limres-rpd-flux1 ]; then echo "STOP: /dev/shm/limres-rpd-flux1 could not be removed"; else echo "removed /dev/shm/limres-rpd-flux1"; fi
  fi
  echo "== rpd-p0-connect rc=$1 $(date -u +%FT%TZ)"; rm -f -- "$SELF"; exit "$1"
}
trap 'echo "STOP: the connect got SIGTERM"; finish 8' TERM
trap 'echo "STOP: the connect got SIGINT"; finish 8' INT
trap 'echo "STOP: the connect got SIGHUP"; finish 8' HUP
case "$(hostname)" in login*) ;; *) echo "STOP: not a login node: $(hostname)"; finish 9 ;; esac
[ ! -e /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126 ] || { echo "STOP: /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126 exists"; finish 9; }
echo "node $(hostname) $(date -u +%FT%TZ); connect script sha256 $(sha256sum "$SELF" | cut -d' ' -f1)"
echo "== 2. the fence (cov2d*, t2a*, rpd*, geanttw* refuse)"
start=$(date -u -d '14 days ago' +%F) || { echo "STOP: start date failed"; finish 3; }
[[ $start =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "STOP: start date malformed: '$start'"; finish 3; }
q=$(sacct -X -n -P -u josephrb -S "$start" -o JobID,JobName,State 2>&1) || { echo "STOP: sacct failed"; printf '%s\n' "$q" | sed 's/^/sacct: /'; finish 3; }
v=$(printf '%s\n' "$q" | awk -F'|' '
  BEGIN { split("BOOT_FAIL CANCELLED COMPLETED DEADLINE FAILED NODE_FAIL OUT_OF_MEMORY PREEMPTED TIMEOUT", t, " ")
          for (i in t) term[t[i]] = 1 }
  /^$/ { next }
  { rows++ }
  NF != 3 || $1 !~ /^[0-9]+([_+].*)?$/ || $2 == "" || $2 ~ /^[[:space:]]|[[:space:]]$/ || $3 !~ /[^[:space:]]/ { print "malformed: " $0; bad = 1; next }
  { split($3, w, " "); if (!(w[1] in term)) print "unended: " $0 }
  tolower($2) ~ /^(cov2d|t2a|rpd|geanttw)/ { n++; if (!(w[1] in term)) bad = 1 }
  END { print "sacct rows (14 days): " rows + 0 "; cov2d/t2a/rpd/geanttw rows: " n + 0; exit bad }')
rc=$?
printf '%s\n' "$v" | sed '/^$/d'
[ "$rc" -eq 0 ] || { echo "STOP: a cov2d/t2a/rpd/geanttw job is unended, or a sacct line is malformed"; finish 3; }
echo "FENCE: clear"
mkdir -m 700 /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126 || finish 9
TMPDIR=/pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126; export TMPDIR  # bash spools heredocs here, inside the root
echo "== 3. fresh clone at $S"
git clone --quiet --filter=blob:none --no-checkout https://github.com/josephbaileyy/MINERvA-OmniFold.git \
  /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/clone || { echo "STOP: clone failed"; finish 5; }
git -C /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/clone fetch --quiet origin "$S" || { echo "STOP: fetch of $S failed"; finish 5; }
git -C /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/clone -c advice.detachedHead=false checkout --quiet "$S" || { echo "STOP: checkout failed"; finish 5; }
head=$(git -C /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/clone rev-parse HEAD)
st=$(git -C /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/clone status --porcelain) || { echo "STOP: git status failed"; finish 5; }
porc=$(printf '%s' "$st" | grep -c '^')
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "$S" ] && [ "$porc" -eq 0 ] || { echo "STOP: the clone is not $S clean"; finish 5; }
while read -r want f; do
  got=$(sha256sum "/pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/clone/$f" | cut -d' ' -f1)
  echo "sha256 $got $f"
  [ "$got" = "$want" ] || { echo "STOP: $f is not at its pinned sha256 $want"; finish 5; }
done <<'PINS'
