got=$(sha256sum /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/p0_expected.json | cut -d' ' -f1)
echo "sha256 $got (expected $EXPECTED_SHA) tools/p0_expected.json"
[ "$got" = "$EXPECTED_SHA" ] || { echo "STOP: expected-values digest"; finish 5; }
got=$(sha256sum /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/p0_supervise.py | cut -d' ' -f1)
echo "sha256 $got (expected $SUPERVISE_SHA) tools/p0_supervise.py"
[ "$got" = "$SUPERVISE_SHA" ] || { echo "STOP: supervisor digest"; finish 5; }
nice -n 19 "$PY" -I -B /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/p0_checks.py inputs /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/p0_expected.json > /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/flux4-inputs.txt 2>&1
