cat /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/flux4-inputs.txt; echo "inputs check rc=$irc"
[ "$irc" -eq 0 ] || { echo "STOP: an in-place input is missing or differs from the committed records"; finish 3; }
echo "== 6. a fresh stat of the gen2thin flux files, the dumps, the omnifiles and the sidecar (against the records)"
nice -n 19 "$PY" -I -B /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/p0_checks.py stat /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/p0_expected.json > /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/stat-p0.txt 2>&1
src=$?
cat /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/stat-p0.txt; echo "stat check rc=$src"
[ "$src" -eq 0 ] || { echo "STOP: a file is missing, or its bytes or inode differ from the record"; finish 3; }
echo "== 7. the overlap fence"
printf '%s' '' | base64 -d > /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/fence_overlap.py
got=$(sha256sum /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/fence_overlap.py | cut -d' ' -f1)
echo "sha256 $got (expected $FENCE_SHA) tools/fence_overlap.py"
[ "$got" = "$FENCE_SHA" ] || { echo "STOP: fence tool digest"; finish 5; }
"$MAT_PYTHON" -I -B /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/tools/fence_overlap.py \
  /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/production-config.ready.json \
  /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/clone > /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/fence-overlap.txt 2>&1
frc=$?
cat /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/fence-overlap.txt; echo "overlap fence rc=$frc"
[ "$frc" -eq 0 ] || { echo "STOP: the overlap fence did not clear; nothing is started"; finish 3; }
echo "== 8. the clone to /dev/shm/limres-rpd-flux1/repo"
[ ! -e /dev/shm/limres-rpd-flux1 ] || { echo "STOP: /dev/shm/limres-rpd-flux1 exists on this node"; finish 9; }
mkdir -m 700 /dev/shm/limres-rpd-flux1 || finish 9
made=1
cp -a /pscratch/sd/j/josephrb/rpd-reco-p0e1-20261126/clone /dev/shm/limres-rpd-flux1/repo || { echo "STOP: copy of the clone"; finish 5; }
head=$(git -C /dev/shm/limres-rpd-flux1/repo rev-parse HEAD)
st=$(git -C /dev/shm/limres-rpd-flux1/repo status --porcelain) || { echo "STOP: git status failed"; finish 5; }
porc=$(printf '%s' "$st" | grep -c '^')
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "$S" ] && [ "$porc" -eq 0 ] || { echo "STOP: the copy is not clean at the pinned head"; finish 5; }
while read -r want f; do
  got=$(sha256sum "/dev/shm/limres-rpd-flux1/repo/$f" | cut -d' ' -f1)
